import clsx from 'clsx';

import PohProgress from '@ui-kit/Progress';
interface IWorkoutTargetProgressProps {
  label: string;
  fromLabel: string;
  toLabel: string;
  pct: number;
}
const WorkoutTargetProgress = ({ label, fromLabel, toLabel, pct }: IWorkoutTargetProgressProps) => (
  <div>
    <small className="text-end text-muted">
      {label} ({fromLabel} из {toLabel})
    </small>
    <PohProgress
      containerClassName="mb-2"
      value={pct}
      className={clsx({ 'bg-warning': pct < 50, 'bg-success': pct >= 90 })}
    >
      {Math.round(pct)}%
    </PohProgress>
  </div>
);

export default WorkoutTargetProgress;
