import React from 'react';

import { getWorkoutsTargetStat } from '@apps/Workouts/@services/workoutsTargets.service';
import { IWorkoutTarget, IWorkoutTargetStat } from '@apps/Workouts/@types/workoutsTargets.types';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { formatAltitude, formatDistance } from '@helpers/formatHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohLoader from '@ui-kit/Loader';

import WorkoutTargetStatUserCard from './WorkoutTargetStatUserCard';

interface IWorkoutTargetStatProps extends React.HTMLAttributes<HTMLDivElement> {
  workoutTarget: IWorkoutTarget;
}

const WorkoutTargetStat: React.FC<IWorkoutTargetStatProps> = ({ workoutTarget }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [workoutTargetStat, setWorkoutTargetStat] = React.useState<IWorkoutTargetStat[]>([]);

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);
        const fetchedData = await getWorkoutsTargetStat(workoutTarget.id);
        setWorkoutTargetStat(fetchedData);
      } catch (error) {
        setErr(error as Error);
        console.error(error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, [workoutTarget.id]);

  if (isLoading) {
    return (
      <div className="p-4 text-center">
        <PohLoader />
      </div>
    );
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  return (
    <article key={workoutTarget.id}>
      <PohRow className="border-top mt-3 pt-3">
        <PohCol sm={9}>
          <h5 className="mb-0">
            <b>{workoutTarget.name}</b> &nbsp;{' '}
            <small className="text-muted">
              {workoutTarget.type?.name ?? 'Все типы активностей'}
            </small>
          </h5>

          {workoutTarget.description?.length > 0 && <p>{workoutTarget.description}</p>}
        </PohCol>
        <PohCol sm={3} className="text-end">
          <div>
            <small className="text-muted">
              {dateRangeToLocaleString(workoutTarget.date_start, workoutTarget.date_finish)}
            </small>
          </div>
        </PohCol>
      </PohRow>

      <PohRow>
        <PohCol sm={3} className="border-end">
          <h6>Цели:</h6>
          {workoutTarget.distance && workoutTarget.distance > 0 && (
            <PohRow>
              <PohCol xs={8} className="text-end text-muted">
                Расстояние
              </PohCol>
              <PohCol xs={4} className="text-success text-nowrap">
                {formatDistance(workoutTarget.distance)}
              </PohCol>
            </PohRow>
          )}

          {workoutTarget.time_moving && workoutTarget.time_moving > 0 && (
            <PohRow>
              <PohCol xs={8} className="text-end text-muted">
                Время в движении
              </PohCol>
              <PohCol xs={4} className="text-success text-nowrap">
                {(workoutTarget.time_moving / 60 / 60).toFixed(1)} ч
              </PohCol>
            </PohRow>
          )}

          {workoutTarget.speed_avg && workoutTarget.speed_avg > 0 && (
            <PohRow>
              <PohCol xs={8} className="text-end text-muted">
                Средняя скорость
              </PohCol>
              <PohCol xs={4} className="text-success text-nowrap">
                {(+workoutTarget.speed_avg).toFixed(1)} км/ч
              </PohCol>
            </PohRow>
          )}

          {workoutTarget.alt_ascent && workoutTarget.alt_ascent > 0 && (
            <PohRow>
              <PohCol xs={8} className="text-end text-muted">
                Набор высоты
              </PohCol>
              <PohCol xs={4} className="text-success text-nowrap">
                {formatAltitude(workoutTarget.alt_ascent)}
              </PohCol>
            </PohRow>
          )}
          {workoutTarget.alt_descent && workoutTarget.alt_descent > 0 && (
            <PohRow>
              <PohCol xs={8} className="text-end text-muted">
                Сброс высоты
              </PohCol>
              <PohCol xs={4} className="text-success text-nowrap">
                {formatAltitude(workoutTarget.alt_descent)}
              </PohCol>
            </PohRow>
          )}
        </PohCol>
        <PohCol sm={9}>
          <h6>Выполнение целей</h6>
          <PohRow>
            {!workoutTargetStat.length && <Empty>Нет тренировок</Empty>}
            {workoutTargetStat.map((wts) => {
              return (
                <PohCol sm={12} lg={6} key={wts.user.id}>
                  <WorkoutTargetStatUserCard
                    workoutTarget={workoutTarget}
                    workoutTargetStat={wts}
                  />
                </PohCol>
              );
            })}
          </PohRow>
        </PohCol>
      </PohRow>
    </article>
  );
};

export default WorkoutTargetStat;
